package com.wheelwright.evidence.v2.portfolio;
import com.fasterxml.jackson.databind.node.ObjectNode;import org.junit.jupiter.api.Test;import java.util.*;import java.time.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioJson.*;import static org.assertj.core.api.Assertions.*;
class PortfolioMoneynessTest {
 static final Instant NOW=PortfolioShareCallShapeTest.now;
 static ObjectNode construction(String right){var c=PortfolioShareCallShapeTest.fixture("100","100","1");((ObjectNode)c.at("/composition/children/1/terms")).put("right",right);((ObjectNode)c.at("/composition/children/1")).put("nodeId","contract");return c;}
 static ObjectNode evaluation(ObjectNode c,String spot,Instant at){var observations=new HashMap<String,ObjectNode>();if(spot!=null){var q=obj().put("receivedAt",at.toString());for(String f:List.of("bid","ask","mid"))q.set(f,metric(new java.math.BigDecimal(spot),"PRICE","USD",at.toString(),"CONTROLLED_MIDPOINT","QUALIFIED",array()));observations.put(c.at("/composition/children/0/instrument/href").asText(),q);}var e=PortfolioMath.evaluate(c,observations,NOW);PortfolioMoneyness.apply(e,c);PortfolioPayoffPlot.apply(e);return e;}
 @Test void exactContractComparisonDoesNotDependOnSideBasisOrRegime(){for(String right:List.of("CALL","PUT"))for(String price:List.of("9","10","11","10.0001"))for(String side:List.of("LONG","SHORT")){
  var c=construction(right);((ObjectNode)c.at("/composition/children/1")).put("side",side);c.put("operatingRegime","UNAVAILABLE");var e=evaluation(c,price,NOW.minusSeconds(1));int cmp=new java.math.BigDecimal(price).compareTo(new java.math.BigDecimal("10"));String expected=cmp==0?"AT_STRIKE":(cmp>0)==right.equals("CALL")?"ITM":"OTM";assertThat(e.at("/moneyness/legs/0/observedState").asText()).isEqualTo(expected);assertThat(e.at("/payoff/geometry/valueKind").asText()).isEqualTo("TERMINAL_VALUE");assertThat(e.at("/grossUnrealizedPl/value").isNull()).isTrue();var before=e.path("moneyness").deepCopy();c.put("operatingRegime","ASSIGNMENT_DESIRED");PortfolioMoneyness.apply(e,c);assertThat(e.path("moneyness")).isEqualTo(before);
 }}
 @Test void dotIsTheExactBackendAffineCurveValueNotPnlOrCurrentHoldingValue(){for(String price:List.of("9","10","11")){var e=evaluation(construction("CALL"),price,NOW.minusSeconds(1));assertThat(e.at("/payoff/geometry/spotPoint/price").asText()).isEqualTo(price);assertThat(e.at("/payoff/geometry/spotPoint/value").asText()).isEqualTo(price.equals("9")?"900":"1000");assertThat(e.at("/payoff/geometry/breakEvenPrices")).isEmpty();}}
 @Test void absentAndHistoricalSpotKeepTheirSeparateMeaning(){var c=construction("CALL");var absent=evaluation(c,null,NOW);assertThat(absent.at("/moneyness/legs/0/observedState").asText()).isEqualTo("UNAVAILABLE");assertThat(absent.at("/payoff/geometry/spotPoint").isMissingNode()).isTrue();assertThat(absent.at("/payoff/status").asText()).isEqualTo("QUALIFIED");var at=NOW.minus(Duration.ofDays(5));var stale=evaluation(c,"9",at);assertThat(stale.at("/moneyness/legs/0/spotAsOf").asText()).isEqualTo(at.toString());assertThat(stale.at("/moneyness/legs/0/spotWarningCodes").toString()).contains("STALE_MARKET_OBSERVATION");}
 @Test void unqualifiedTermsNeverGainRegionsAndVerifiedNon100TermsRemainUsable(){for(String field:List.of("deliverable","multiplier","adjustment","settlement","payoffApplicability")){var c=construction("CALL");((ObjectNode)c.at("/composition/children/1/terms")).remove(field);var e=evaluation(c,"9",NOW);assertThat(e.at("/moneyness/legs/0/status").asText()).as(field).isEqualTo("UNAVAILABLE");assertThat(e.at("/payoff/status").asText()).isNotEqualTo("QUALIFIED");}var c=PortfolioShareCallShapeTest.fixture("100","50","2");var e=evaluation(c,"9",NOW);assertThat(e.at("/moneyness/legs/0/observedState").asText()).isEqualTo("OTM");assertThat(e.at("/payoff/geometry/segments/1/slope").asText()).isEqualTo("0");}
 @Test void multiLegStatesStayPerContractAndForeignSpotIsUnavailable(){var c=construction("CALL");var other=((ObjectNode)c.at("/composition/children/1")).deepCopy();other.put("nodeId","other");((ObjectNode)other.path("terms")).put("right","PUT");((com.fasterxml.jackson.databind.node.ArrayNode)c.at("/composition/children")).add(other);var e=evaluation(c,"9",NOW);assertThat(e.at("/moneyness/legs/0/observedState").asText()).isEqualTo("OTM");assertThat(e.at("/moneyness/legs/1/observedState").asText()).isEqualTo("ITM");assertThat(e.at("/moneyness/observedState").isMissingNode()).isTrue();((ObjectNode)e.path("spot")).put("currency","EUR");PortfolioMoneyness.apply(e,c);assertThat(e.at("/moneyness/legs/0/observedState").asText()).isEqualTo("UNAVAILABLE");}
 @Test void invalidUnknownFutureAndForeignUnderlyingClocksDoNotBecomeObservedMoneyness(){
  for(String time:List.of("unknown","2026-10-30T16:00:00Z")){var c=construction("CALL");var e=evaluation(c,"9",NOW);((ObjectNode)e.path("spot")).put("asOf",time);PortfolioMoneyness.apply(e,c);PortfolioPayoffPlot.apply(e);assertThat(e.at("/moneyness/legs/0/observedState").asText()).isEqualTo("UNAVAILABLE");assertThat(e.at("/payoff/geometry/spotPoint").isMissingNode()).isTrue();}
  var c=construction("CALL");var e=evaluation(c,"9",NOW);((ObjectNode)c.at("/composition/children/0/instrument")).put("href","/v2/instruments/foreign");PortfolioMoneyness.apply(e,c);assertThat(e.at("/moneyness/legs/0/observedState").asText()).isEqualTo("UNAVAILABLE");
 }

}
